<?php
require_once __DIR__.'/../includes/staff/feature-tools.php';$pdo=staff_db();$token=$_GET['token']??'';$user=null;$customer=null;if(isset($_GET['logout'])){unset($_SESSION['customer_portal_user_id']);header('Location: '.ideare_root_url('pages/customer-portal.php'));exit;}if($token!==''){try{$hash=hash('sha256',$token);$q=$pdo->prepare('SELECT u.*,t.id token_id FROM customer_portal_tokens t JOIN customer_users u ON u.id=t.customer_user_id WHERE t.token_hash=? AND t.expires_at>NOW() AND t.used_at IS NULL AND u.is_active=1 LIMIT 1');$q->execute([$hash]);$user=$q->fetch(PDO::FETCH_ASSOC);if($user){$pdo->prepare('UPDATE customer_portal_tokens SET used_at=NOW() WHERE id=?')->execute([$user['token_id']]);$_SESSION['customer_portal_user_id']=$user['id'];$pdo->prepare('UPDATE customer_users SET last_login_at=NOW() WHERE id=?')->execute([$user['id']]);$customer=db_one($pdo,'SELECT * FROM customers WHERE id=?',[$user['customer_id']]);}}catch(Throwable $e){}}elseif(!empty($_SESSION['customer_portal_user_id'])){$user=db_one($pdo,'SELECT * FROM customer_users WHERE id=? AND is_active=1',[(int)$_SESSION['customer_portal_user_id']]);if($user)$customer=db_one($pdo,'SELECT * FROM customers WHERE id=?',[$user['customer_id']]);}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Customer Portal · IdeaRE</title><link rel="stylesheet" href="<?=h(ideare_root_url('assets/css/staff.css'))?>"><link rel="stylesheet" href="<?=h(ideare_root_url('assets/css/crm-projects.css'))?>"></head><body><main class="portal-shell"><h1>IdeaRE Customer Portal</h1><?php if(!$user):?><section class="staff-panel"><p>This portal link is missing, expired, or already used. Please request a fresh secure link from the IdeaRE team.</p></section><?php else:$projects=db_rows($pdo,'SELECT * FROM projects WHERE customer_id=? ORDER BY updated_at DESC',[$customer['id']]);$invoices=db_rows($pdo,'SELECT * FROM invoices WHERE customer_id=? ORDER BY created_at DESC',[$customer['id']]);$docs=db_rows($pdo,'SELECT * FROM documents WHERE customer_id=? AND is_customer_visible=1 ORDER BY created_at DESC',[$customer['id']]);?><p>Welcome, <?=h($customer['name'])?>.</p><div class="module-grid"><?php foreach($projects as $p):?><div class="metric-card"><small><?=h($p['project_code'])?></small><strong style="font-size:20px"><?=h($p['name'])?></strong><span class="pill"><?=h($p['status'])?></span><p>Target: <?=h($p['target_date']?:'To be confirmed')?></p></div><?php endforeach?></div><section class="staff-panel table-panel"><h2>Invoices</h2><table><thead><tr><th>Invoice</th><th>Total</th><th>Paid</th><th>Balance</th><th>Status</th></tr></thead><tbody><?php foreach($invoices as $i):?><tr><td><?=h($i['invoice_no'])?></td><td>RM <?=number_format($i['total_amount'],2)?></td><td>RM <?=number_format($i['paid_amount'],2)?></td><td>RM <?=number_format($i['balance_amount'],2)?></td><td><?=h($i['status'])?></td></tr><?php endforeach?></tbody></table></section><section class="staff-panel"><h2>Documents</h2><?php foreach($docs as $d):?><div class="board-card"><b><?=h($d['title'])?></b><small><?=h($d['category'])?></small></div><?php endforeach?></section><?php endif?></main></body></html>